class MagicOrb {
  #energyLevel; // Private field declaration

  constructor(initialEnergy) {
    this.#energyLevel = initialEnergy;
    if (this.#energyLevel < 0) this.#energyLevel = 0;
    if (this.#energyLevel > 100) this.#energyLevel = 100;
  }

  charge(amount) {
    if (typeof amount !== 'number' || amount < 0) {
      console.warn("Charge amount must be a positive number.");
      return;
    }
    this.#energyLevel = Math.min(100, this.#energyLevel + amount);
  }

  discharge(amount) {
    if (typeof amount !== 'number' || amount < 0) {
      console.warn("Discharge amount must be a positive number.");
      return;
    }
    this.#energyLevel = Math.max(0, this.#energyLevel - amount);
  }

  getEnergyLevel() {
    return this.#energyLevel;
  }
}

// Example Usage (for testing):
const orb = new MagicOrb(50);
console.log(`Initial energy: ${orb.getEnergyLevel()}`); // Expected: 50
orb.charge(30);
console.log(`After charging 30: ${orb.getEnergyLevel()}`); // Expected: 80
orb.discharge(90);
console.log(`After discharging 90: ${orb.getEnergyLevel()}`); // Expected: 0
orb.charge(200); // Attempt to overcharge
console.log(`After overcharging: ${orb.getEnergyLevel()}`); // Expected: 100
orb.discharge(5); 
console.log(`After discharging 5: ${orb.getEnergyLevel()}`); // Expected: 95

